import React, { useMemo, useState } from 'react';
import { williamsFamilyTree } from '../../modules/family-tree';

// 1. Recursive node renderer
const PersonNode = ({ node }:{ node: any}) => {
  const [showChildren, setShowChildren] = useState(true);

  if (!node) return null;

  const hasChildren = node.children.length > 0;

  const toggleChildren = () => {
    if (hasChildren) setShowChildren(prev => !prev);
  };

  return (
    <div className="person">
      <span
        className="person-name"
        onClick={toggleChildren}
        style={{ cursor: hasChildren ? 'pointer' : 'default' }}
      >
        {hasChildren && (showChildren ? '▾ ' : '▸ ')}
        {node.name}
      </span>

      {hasChildren && showChildren && (
        <div className="children">
          {node.children.map((child: any) => (
            <PersonNode key={child.id} node={child} />
          ))}
        </div>
      )}
    </div>
  );
};

// 2. Wrapper that kicks off rendering from the root
const WilliamsFamilyTree = ({ tree }:{tree: any}) => <PersonNode node={tree} />;

const buildTree = (id: any, people: any, seen = new Set()) => {
  if (seen.has(id)) return null;
  seen.add(id);

  const person = people[id];
  return {
    ...person,
    children: person.childIds.map((cid: any) => buildTree(cid, people, seen)),
  };
};


const FamilyTree = () => {
    const rootId = 'p1'; // whichever person is the top of the tree

  const tree = useMemo(
    () => buildTree(rootId, williamsFamilyTree),
    [rootId]
  );

  return <WilliamsFamilyTree tree={tree} />;
}

export default FamilyTree;